# Seven Lean Principles (JSON)
{
  "lean_principles": [
    {
      "principle": 1,
      "name": "Eliminate Waste",
      "description": "Remove activities that don't add value",
      "examples_of_waste": [
        "Partial work (incomplete features)",
        "Extra processes (unnecessary approvals)",
        "Unclear requirements (leading to rework)",
        "Delayed information sharing"
      ]
    },
    {
      "principle": 2,
      "name": "Amplify Learning",
      "description": "Continuous improvement through feedback",
      "practices": ["Code reviews", "Retrospectives", "A/B testing"]
    },
    {
      "principle": 3,
      "name": "Decide as Late as Possible",
      "description": "Keep options open to adapt to new information",
      "benefit": "Reversibility of decisions"
    },
    {
      "principle": 4,
      "name": "Deliver as Fast as Possible",
      "description": "Reduce lead time to market",
      "benefit": "Faster feedback, earlier ROI"
    },
    {
      "principle": 5,
      "name": "Empower the Team",
      "description": "Give autonomy to make decisions",
      "benefit": "Speed and morale"
    },
    {
      "principle": 6,
      "name": "Build Quality In",
      "description": "Prevent defects rather than detect them",
      "practices": ["TDD", "Pair programming", "Continuous integration"]
    },
    {
      "principle": 7,
      "name": "See the Whole",
      "description": "Optimize the system, not individual parts",
      "focus": "End-to-end value delivery"
    }
  ]
}
